<?php
declare(strict_types=1);
final class PCStoryRepository {
 public static function canView(PDO $p,int $uid,int $sid):bool{$s=$p->prepare("SELECT 1 FROM stories s WHERE s.id=? AND s.expires_at>UTC_TIMESTAMP() AND (s.author_id=? OR s.visibility='everyone' OR (s.visibility='friends' AND EXISTS(SELECT 1 FROM friendships f WHERE f.user_id=? AND f.friend_id=s.author_id))) AND NOT EXISTS(SELECT 1 FROM user_blocks b WHERE (b.user_id=? AND b.blocked_user_id=s.author_id) OR (b.user_id=s.author_id AND b.blocked_user_id=?)) LIMIT 1");$s->execute([$sid,$uid,$uid,$uid,$uid]);return (bool)$s->fetchColumn();}
 public static function feed(PDO $p,int $uid):array{$s=$p->prepare("SELECT s.id,s.author_id,u.username,s.encrypted_payload,s.encryption_version,s.visibility,s.expires_at,s.created_at,(SELECT COUNT(*) FROM story_views v WHERE v.story_id=s.id) views_count,EXISTS(SELECT 1 FROM story_views v WHERE v.story_id=s.id AND v.viewer_id=?) viewed_by_me FROM stories s JOIN users u ON u.id=s.author_id WHERE s.expires_at>UTC_TIMESTAMP() AND (s.author_id=? OR s.visibility='everyone' OR (s.visibility='friends' AND EXISTS(SELECT 1 FROM friendships f WHERE f.user_id=? AND f.friend_id=s.author_id))) AND NOT EXISTS(SELECT 1 FROM user_blocks b WHERE (b.user_id=? AND b.blocked_user_id=s.author_id) OR (b.user_id=s.author_id AND b.blocked_user_id=?)) ORDER BY s.created_at DESC LIMIT 200");$s->execute([$uid,$uid,$uid,$uid,$uid]);return array_map(static fn(array $r):array=>['id'=>(string)$r['id'],'author_id'=>(string)$r['author_id'],'username'=>$r['username'],'payload'=>$r['encrypted_payload'],'encrypted'=>true,'encryption_version'=>$r['encryption_version'],'visibility'=>$r['visibility'],'expires_at'=>$r['expires_at'],'created_at'=>$r['created_at'],'views_count'=>(int)$r['views_count'],'viewed_by_me'=>(bool)$r['viewed_by_me']],$s->fetchAll());}
 public static function create(PDO $p,int $uid,string $payload,string $visibility,int $hours):int{$expiry=gmdate('Y-m-d H:i:s',time()+($hours*3600));$s=$p->prepare('INSERT INTO stories (author_id,encrypted_payload,encryption_version,visibility,expires_at) VALUES (?,?,\'pc-e2ee-v1\',?,?)');$s->execute([$uid,$payload,$visibility,$expiry]);return (int)$p->lastInsertId();}
 public static function markViewed(PDO $p,int $uid,int $sid):void{$p->prepare('INSERT INTO story_views (story_id,viewer_id,viewed_at) VALUES (?,?,UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE viewed_at=VALUES(viewed_at)')->execute([$sid,$uid]);}
 public static function delete(PDO $p,int $uid,int $sid):bool{$s=$p->prepare('DELETE FROM stories WHERE id=? AND author_id=?');$s->execute([$sid,$uid]);return $s->rowCount()>0;}
}
